# Hypothesis: within each 3x3 block, if a nonzero color's cells form exactly ONE connected component (4 or 8-conn), output it; else 0.
def comps8(grid):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; cs=[]
    for i in range(H):
        for j in range(W):
            v=grid[i][j]
            if v!=5 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            n=(a+da,b+db)
                            if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and grid[n[0]][n[1]]==v:
                                seen[n[0]][n[1]]=True; st.append(n)
                cs.append(comp)
    return cs
