# simpler: mode among all cells in block, unless mode is 5 -> 0
def f_mode2(inp):
    O=len(inp)//3; out=[]
    for i in range(O):
        row=[]
        for j in range(len(inp[0])//3):
            cnt=collections.Counter(inp[r0+a][c0+b] for a in range(3) for b in range(3))
            top=cnt.most_common(1)[0]
            row.append(top[0] if top[0]!=5 else 0)
        out.append(row)
